{
  "kind": "自己仮説・固定状態の本文計算。実戦観察・勝率・自己reviewではない",
  "fixed_state": {
    "turn": "自分後攻T8開始（8PP）。相手次ターン先攻T9（9PP）。エクストラPP使用済み。",
    "own": "体力3、EP0 SEP0、場0、手札5枚。EPはT4/T5、SEPはT6/T7に各1回使った状態として合法。",
    "common_four": "+3マガチヨ5/5、+3セタス＆メイシア7/9、事前に生成した森の神秘2枚。交換札は同じ時点の引き込みに対応する+1ベア7/7または+1ヒエン5/5。",
    "enemy_board": "+3ミロク5/5と+3マガチヨ5/5。どちらも進化前、登場時能力は解決済み、守護等の追加能力なし。",
    "enemy_resources": "体力12、返しは9PP、EP0 SEP1、ターン開始ドローを含む手札5枚を各行で全指定。追加の信仰・クレスト誘発なし。場のマガチヨ1枚とケースBの手札2枚の合計は3枚。"
  },
  "own_lines": [
    {
      "line": "ベア",
      "actions": "森の神秘0を2枚使い、体力3→5、手札5→3。ベア8を使い手札2・PP0・場2。7/7を2体出し、それぞれ相手5/5へ突進して両方倒す。各被ダメージ5→3で7/4守護2体。EP SEPは使わない。",
      "remaining": "自分体力5、PP0、手札はマガチヨとセタス＆メイシアの2枚、場7/4守護2体。相手体力12。"
    },
    {
      "line": "従来の防御（セタス＆メイシア）",
      "actions": "同じ森の神秘2枚で体力5。セタス＆メイシア7を使い片方を破壊、7/9疾走で残る5/5へ攻撃し、7/4守護1体を残す。",
      "remaining": "自分体力5、PP1、手札はマガチヨとヒエンの2枚。相手体力12。失った攻撃機会は、このターンのセタス＆メイシアによるリーダー7点。顔へ7点なら相手は5で生き、残した5/5と返しのマガチヨで守護を倒され敗北する。"
    },
    {
      "line": "従来の他の候補",
      "actions": "神秘2枚→マガチヨ3では相手2体とも5/1、PP5。ヒエンは6コストで同ターンに使えず、セタス＆メイシア7も使えない。神秘2枚→ヒエン7は片方への4点だけで突進・守護がなく、進化権もない。マガチヨ3＋セタス＆メイシア7は10PP。神秘を使わない分岐もこれらの支払額・回復不足を改善しない。"
    }
  ],
  "opponent_responses": [
    {
      "case": "A：全体ダメージ1枚＋ヒエン",
      "full_hand": "森の神秘2、無強化マガチヨ1、無強化ヒエン1、無強化セタス＆メイシア1。",
      "versus_baseline": "神秘0×2→マガチヨ3でコンボ3、4点で7/4守護を破壊。マガチヨをSEPで5/5疾走にして顔5点。自分体力5→0。相手残6PP、手札ヒエン・セタス＆メイシア、SEP0。",
      "versus_bear": "同じ4点は各3となり7/1が2体残る。神秘×2→マガチヨ3の後、ヒエンは6コスト（最初から手札にあり先行3プレイで軽減）。ヒエン6の4点で片方を破壊し、SEPマガチヨ5/5が残る守護を攻撃して破壊するとリーダーへ1点。相手残0PP、手札セタス＆メイシア、場SEPマガチヨ5/5＋ヒエン4/4。自分体力4で次のターンを迎える。ヒエンを使わなければ守護を1体残す。セタス＆メイシア7単独は1体破壊後、攻撃がもう1体の体力4を3だけ減らすため顔へ通らない。",
      "gain_limit": "この全手札では、従来の守護1体を除去して顔へ使えたマガチヨの攻撃を、ベアは守護への攻撃へ変える。相手に追加6PPとヒエン1枚を使わせる比較。次の自分の勝利やベアの生存を保証しない。"
    },
    {
      "case": "B：全体ダメージ2枚",
      "full_hand": "森の神秘2、無強化マガチヨ2、無強化セタス＆メイシア1。",
      "versus_baseline": "神秘×2→マガチヨ3→SEP顔5。相手残6PP、マガチヨ1枚は温存できる。",
      "versus_bear": "神秘×2→マガチヨ3→マガチヨ3で各3点を2回。7/4守護2体は両方倒れ、どちらかをSEPして顔5で敗北。相手残3PP、セタス＆メイシア1枚。",
      "gain_limit": "ベアは追加3PP・マガチヨ1枚を要求するが、このターンの敗北を防がない。3回強化の9/6でも同じ2回で倒れる。"
    },
    {
      "case": "C：必殺2体",
      "full_hand": "森の神秘2、無強化根差の刺客2、無強化マガチヨ1。",
      "versus_baseline": "神秘×2→根差2（コンボ3で必殺フェアリー生成）→フェアリー1で守護を破壊→マガチヨ3をSEPし顔5。計6PP、残3PP、根差1枚を温存。",
      "versus_bear": "神秘×2→根差2→必殺フェアリー1で片方を破壊→根差2→必殺フェアリー1でもう片方を破壊→マガチヨ3をSEPし顔5。計9PP、手札0、場は根差2体とSEPマガチヨ1体。各フェアリーは交戦で死亡するが必殺で対象も倒れる。",
      "gain_limit": "追加3PPと根差1枚を要求するが敗北を防がない。強化回数を増やしても必殺への耐性は得ない。"
    },
    {
      "case": "D：破壊2枚",
      "full_hand": "森の神秘2、慈愛の天槍2、無強化マガチヨ1。天槍は固定の対象プール内にあるが比較元Game8の40枚にはない。",
      "versus_baseline": "天槍3で唯一の守護を破壊→神秘2枚→マガチヨ3をSEPして顔5。計6PP。",
      "versus_bear": "天槍3×2の破壊モードで守護2体を順に破壊。対象が同攻撃力でもどちらか1体ずつ必ず倒れる。神秘2枚→マガチヨ3をSEPし顔5。計9PP。",
      "gain_limit": "追加3PPと天槍1枚を要求するが敗北を防がない。採用頻度は調べておらず、この相手が一般的との主張はしない。"
    },
    {
      "case": "E：体力減少を含む返し",
      "full_hand": "Aのヒエンを+3ダストデイズ6/6に変更。他4枚は同じ。",
      "versus_baseline": "Aと同じマガチヨ3＋SEP顔で敗北。",
      "versus_bear": "神秘×2→ダストデイズ4の体力-6で片方を破壊→マガチヨ3全体4点で残りは7/1→SEPマガチヨが残る守護を攻撃してリーダー1点。計7PP、残2PP、手札セタス＆メイシア。自分体力4。",
      "gain_limit": "守護2体を安く処理されるが、指定した残り手札ではマガチヨの攻撃は顔へ回せない。残る2PPで使える別の攻撃札があれば結果は変わる。未指定の札を後から追加しない。"
    }
  ],
  "sensitivity": [
    "開始体力3を神秘2枚で5にする比較であり、回復札の不足や異なる残り体力へ生存差を一般化しない。",
    "自分にSEP1が残る場合、従来のセタス＆メイシアを10/12へ超進化し、交戦ダメージ0で相手を処理できる。Aのマガチヨ4点＋ヒエン4点だけでは体力4を残し、マガチヨの攻撃を守護へ使わせる。したがって今回の生存差は進化権を使い切った状況で明瞭になる。自分の超進化による盤面処理では相手体力12→11の1点も生じる。",
    "先攻T8にSEP0を置くと不可能な消費履歴になるため、その条件は採用しなかった。",
    "旧ベア案の課題である8PPの遅さ、引けない問題、早い攻撃機会の喪失は未解消。1回強化でも働く境目があるため3回強化とT8ぴったりの引き込みは必須にしない。"
  ]
}

{
  "kind": "自己仮説・一連の支払と上限の確認。実戦・到達率の証明ではない。前後局面はfixed-state-comparisonと別の指定例。",
  "start": "先攻T5、PP5、EP2 SEP2、場0、手札はダストデイズ、発芽の組員、二枚看板A、二枚看板B、舎弟頭の5枚。ベアは山札。相手はダストデイズで倒せる体力3のフォロワー1体。開始以前の手札の集まり方・両リーダーの体力は未確認。",
  "turns": [
    {
      "turn": "T5",
      "actions": "ダストデイズ4で相手の体力を3減らし除去。コンボ2、EP進化で5/5とクレスト。発芽1を3枚目として使い、鹿王を引く。",
      "account": "PP5→1→0。手札5→4→3→4。場0→1→2。EP2→1、SEP2のまま。終了時コンボ3で山札のベアが7/7（強化1回）。",
      "hand_end": "二枚看板A、二枚看板B、舎弟頭、鹿王。"
    },
    {
      "turn": "T6（早めに引く本線）",
      "actions": "通常ドローがベア7/7で手札5。保持して山札へ戻さない。二枚看板A2で森の神秘・フェアリーを生成。神秘0を使いコンボ2。舎弟頭2を3枚目として使い、マガチヨAと発芽Bを引く（どちらも強化1回）。",
      "account": "PP6→4→4→2。手札5→4+2=6→5→4+2=6。場はT5の2体が残っていても舎弟頭を加え最大3。EP1 SEP2を維持。終了時コンボ3で山札だけが2回目の強化。手札のベアは7/7のまま。",
      "hand_end": "二枚看板B、鹿王、ベア7/7、フェアリーA、マガチヨA3/3、発芽B2/2。"
    },
    {
      "turn": "T7",
      "actions": "通常ドローがセタス＆メイシア6/8（強化2回）で手札7。相手の場は強化2回・進化前のミロク4/4とマガチヨ4/4（登場時能力は解決済み）。T5の発芽1/1がまだ場に残る場合は一方を攻撃して自分を死亡させる。既に除去されていればこの行動は不要。二枚看板B2で神秘・フェアリーを生成、神秘0、発芽B1を3枚目として使いヒエン6/6を引く。発芽B2/2で相手4/4の一方へ攻撃し自身は死亡。マガチヨA3を4枚目として使い全体4点で相手2体を処理する。",
      "account": "PP7→5→5→4→1。手札7→6+2=8→7→6+1=7→6。T5の発芽が残れば攻撃で場を空け、残らなければ既にその1枠は空いている。新しい発芽の登場時は最大3、交戦死亡後は最大2、マガチヨで最大3。EP1 SEP2を維持。終了時コンボ4で山札だけが3回目の強化。ベア7/7は保持。",
      "hand_end": "鹿王、ベア7/7、フェアリーA、セタス＆メイシア6/8、フェアリーB、ヒエン6/6。"
    },
    {
      "turn": "T8",
      "actions": "通常ドローがマガチヨB5/5（強化3回）で手札7。相手に倒された味方が0体でも自分の場は最大3なので、ベア8を使って本体とコピーを出せる。",
      "account": "PP8→0、手札7→6、場は最大3→5。EP1 SEP2を維持。ベアは7/7が2体。相手ターンを生き延びてT8へ来られたこと自体は、この手札会計だけでは証明しない。"
    }
  ],
  "branches": [
    {
      "branch": "3回強化後に引く場合",
      "detail": "T6通常ドローをベアではなく別のマガチヨ3/3とし、その他の同じ行動でベアを山札に残す。T8通常ドローがベアなら9/9を出せる。支払・手札・場の上限は同じ。これは特定ドローを置いた上限例で、今回の方針の必須条件にはしない。"
    },
    {
      "branch": "T5以前に無強化で引いた場合",
      "detail": "無強化6/6では5点交戦→4点全体除去の2回で体力6→3→0。トラッパーがT5の発芽の代わりに手札にあるなら、ダストデイズ4→EP→トラッパー1でベアを戻してフェアリー2枚を得つつコンボ3を満たす。手札にベアを含む5枚なら5→4→3→2+2=4。場2。最初の強化は受けられるが、発芽の1ドローを失い再取得は保証されない。トラッパーは比較元で1枚のみ。ベアのためだけに戻し札を増やさない。"
    },
    {
      "branch": "必要なときに引けない場合",
      "detail": "ベアは採用1枚、舎弟頭の補充は指定したカードを引く効果ではない。引けなければ既存のマガチヨ・セタス＆メイシアの計画へ戻る。ベア取得前提で疾走や進化権を全部消費する運用にはしない。"
    },
    {
      "branch": "後攻T7に8PP",
      "detail": "後攻の後半エクストラPPを保持していればT7の7PPを8にして、既に手札にあるベアを使える。本文上の補助だけを確認し、後攻T4からT7までの別の全手順・両リーダー体力は未接続。"
    }
  ],
  "lost_hien_opportunity": "既存注記どおり、後攻T5に初めから手札のヒエンと事前生成のフェアリー・森の神秘、ミロク、EP1、前半エクストラPPを持つ指定状態なら、PP5→フェアリー1で4→ミロク3で1→登場時回復で3→EP進化回復で5→神秘0→エクストラPPで6→3プレイで6コストのヒエンを出せる。同じ手札のヒエン枠がベアなら8コストを払えない。ベア採用はこの早い攻撃体と復活の機会を1枚分減らす。既知の早出しを新発見として再提案しない。",
  "not_resolved": [
    "各ターンの生存・必要札の取得率・相手がこの盤面を置く頻度。",
    "T6の残2PP、T7の残1PPは未使用として計上。余裕を別の働きへ勝手に加算しない。",
    "低コスト除去と補充によって古いベア構築がどの程度改善したかの実戦比較。",
    "後攻T8・EP/SEP0の局面比較と、この先攻T5開始の到達例は別であり、同一の完全対戦記録ではない。"
  ],
  "construction_corrections": [
    "作成途中でT7の相手2体を+3の5/5から+2の4/4へ訂正。相手後攻T6に出すなら山札強化3回目の終了より前なので、T4開始の強化だけでは+3を受けて手札にない。場の空きはT5の発芽が残った場合に攻撃して死亡する分岐で確保する。独立評価後の改訂や実戦結果の訂正ではなく、今回提出前の本文計算の修正。"
  ]
}

